const workflowContext = this;
const env = $env || {};

const headers = ($json && $json.headers) ? $json.headers : {};
const body = ($json && $json.body) ? $json.body : ($json ?? {});

function required(value, name) {
  if (value === undefined || value === null || String(value).trim() === '') {
    throw new Error(`${name} is required`);
  }
  return value;
}

function trimSlash(value) {
  return String(value || '').replace(/\/+$/, '');
}

function safeString(value) {
  if (value === undefined || value === null) return '';
  return String(value).trim();
}

function getHeader(name) {
  const lower = String(name || '').toLowerCase();
  if (headers[lower] !== undefined) return headers[lower];
  if (headers[name] !== undefined) return headers[name];
  const key = Object.keys(headers).find((k) => k.toLowerCase() === lower);
  return key ? headers[key] : undefined;
}

const realm = safeString(body.realm || env.N8N_REALM || env.N8N_OBSERVER_REALM || 'default') || 'default';

const gitlabBaseUrl = trimSlash(
  body.gitlab_base_url ||
  body.GITLAB_BASE_URL ||
  env.N8N_GITLAB_BASE_URL ||
  env.GITLAB_BASE_URL ||
  env.GITLAB_URL ||
  env.SERVICE_URL_GITLAB ||
  ''
);

const gitlabApiBase = trimSlash(
  body.gitlab_api_base_url ||
  body.GITLAB_API_BASE_URL ||
  env.N8N_GITLAB_API_BASE_URL ||
  env.GITLAB_API_BASE_URL ||
  (gitlabBaseUrl ? `${gitlabBaseUrl}/api/v4` : '') ||
  ''
);

const gitlabToken = safeString(env.N8N_GITLAB_TOKEN || env.GITLAB_TOKEN || env.GITLAB_ADMIN_TOKEN || '');

function normalizeProjectRef(value) {
  const v = safeString(value);
  if (!v) return '';
  if (/^\d+$/.test(v)) return v;
  if (v.includes('/')) return v;
  return `${realm}/${v}`;
}

let projectRefRaw = safeString(
  body.HR_TALENT_GITLAB_PROJECT_ID ||
  body.HR_TALENT_GITLAB_PROJECT_PATH ||
  body.HR_TALENT_PROJECT_PATH ||
  body.HR_TALENT_MANAGEMENT_PROJECT_PATH ||
  env.HR_TALENT_GITLAB_PROJECT_ID ||
  env.HR_TALENT_GITLAB_PROJECT_PATH ||
  env.HR_TALENT_PROJECT_PATH ||
  env.HR_TALENT_MANAGEMENT_PROJECT_PATH ||
  env.N8N_GITLAB_PROJECT_ID ||
  env.N8N_GITLAB_PROJECT_PATH ||
  ''
);

let projectRef = normalizeProjectRef(projectRefRaw);
if (!projectRef) {
  projectRef = `${realm}/hr-talent-management`;
}
required(gitlabApiBase, 'GITLAB_API_BASE_URL');
required(gitlabToken, 'GITLAB_TOKEN');
required(projectRef, 'HR_TALENT_GITLAB_PROJECT_ID or HR_TALENT_GITLAB_PROJECT_PATH (or HR_TALENT_PROJECT_PATH)');

const zulipBaseUrl = trimSlash(env.ZULIP_API_BASE_URL || env.N8N_ZULIP_API_BASE_URL || '');
const zulipEmail = safeString(env.ZULIP_BOT_EMAIL || env.ZULIP_EMAIL || '');
const zulipApiKey = safeString(env.ZULIP_BOT_API_KEY || env.ZULIP_API_KEY || '');
const zulipStream = safeString(env.HR_TALENT_ZULIP_STREAM || '');
const zulipTopicDefault = safeString(env.HR_TALENT_ZULIP_TOPIC || 'hr-talent') || 'hr-talent';

async function zulipSendStreamMessage(content, topic) {
  if (!zulipBaseUrl || !zulipEmail || !zulipApiKey || !zulipStream) return null;
  const url = `${zulipBaseUrl}/api/v1/messages`;
  const auth = Buffer.from(`${zulipEmail}:${zulipApiKey}`).toString('base64');
  return await workflowContext.helpers.httpRequest({
    method: 'POST',
    url,
    json: true,
    headers: {
      'Authorization': `Basic ${auth}`,
    },
    form: {
      type: 'stream',
      to: zulipStream,
      topic: topic || zulipTopicDefault,
      content,
    }
  });
}


const personKey = required(safeString(body.person_key || body.personKey), 'person_key');
const skillId = required(safeString(body.skill_id || body.skillId), 'skill_id');
const level = required(safeString(body.level || body.skill_level || body.skillLevel), 'level');

const requestedBy = safeString(body.requested_by || body.requestedBy || getHeader('x-requested-by') || '') || null;
const evidence = safeString(body.evidence || body.evidence_ref || body.evidenceRef || '') || null;
const notes = safeString(body.notes || body.comment || '') || null;

const payload = {
  realm,
  person_key: personKey,
  skill_id: skillId,
  level,
  evidence,
  notes,
  requested_by: requestedBy,
  requested_at: new Date().toISOString(),
};

const payloadMarker = `<!--HR_TALENT_SKILL_UPDATE_JSON:${JSON.stringify(payload)}-->`;

const issueTitle = `Skill update: ${personKey} ${skillId} -> ${level}`;
const labels = [
  'hr-talent',
  'hr-skill-update',
  'status:pending-approval',
  `realm:${realm}`,
];

const issueDescription = [
  '# スキル更新申請',
  '',
  payloadMarker,
  '',
  `- realm: ${realm}`,
  `- person_key: ${personKey}`,
  `- skill_id: ${skillId}`,
  `- level: ${level}`,
  evidence ? `- evidence: ${evidence}` : null,
  requestedBy ? `- requested_by: ${requestedBy}` : null,
  '',
  '## 承認手順（MVP）',
  '- 承認者はコメントで `/approve` を投稿してください（推奨）',
  '- もしくはラベル `status:approved` を付与してください',
  '',
  notes ? `## 補足\n${notes}` : null,
].filter((v) => v !== null).join('\n');

const projectEncoded = encodeURIComponent(projectRef);
const url = `${gitlabApiBase}/projects/${projectEncoded}/issues`;

let issue;
try {
  issue = await workflowContext.helpers.httpRequest({
    method: 'POST',
    url,
    json: true,
    headers: { 'PRIVATE-TOKEN': gitlabToken },
    body: {
      title: issueTitle,
      description: issueDescription,
      labels: labels.join(','),
    }
  });
} catch (err) {
  const status = err?.response?.statusCode || err?.statusCode || err?.httpCode || null;
  const responseBody = err?.response?.body || err?.response?.data || null;
  return [{
    json: {
      ok: false,
      status_code: status || 500,
      error: String(err?.message || err),
      response_body: responseBody,
      realm,
      project_ref: projectRef,
    }
  }];
}


try {
  const msg = [
    'HR Talent: スキル更新申請が作成されました。',
    `- realm: ${realm}`,
    `- person_key: ${personKey}`,
    `- skill_id: ${skillId}`,
    `- level: ${level}`,
    issue?.web_url ? `- issue: ${issue.web_url}` : null,
  ].filter((v) => v !== null).join('\n');
  await zulipSendStreamMessage(msg, 'hr-skill-update');
} catch (err) {
  // ignore zulip failures
}

return [{
  json: {
    ok: true,
    status_code: 200,
    realm,
    project_ref: projectRef,
    issue: {
      id: issue?.id,
      iid: issue?.iid,
      title: issue?.title,
      web_url: issue?.web_url,
      labels: issue?.labels,
    },
    payload,
  }
}];
